		return m*x+c;
	}
};

struct node{
	int s,e,m;
	int vs=0,ve=0,vm=0;
	line val={0,-INF};
	int lazy=0;
	node *l,*r;

	node(int _s,int _e){
		s=_s,e=_e,m=s+e>>1;

		if (s!=e){
			l=new node(s,m);
			r=new node(m+1,e);
		}
	}

	void propo(){
		if (lazy==0) return;

		val.c-=val.m*lazy;
		vs+=lazy;
		ve+=lazy;
		vm+=lazy;

		if (s!=e){
			l->lazy+=lazy;
			r->lazy+=lazy;
		}
		lazy=0;
	}

	void update(int i){
		if (s==i) lazy++;
		else{
			if (val.c!=-INF){
				l->propo(),r->propo();
				l->update(val),r->update(val);
				val={0,-INF};
			}

			if (m<i) r->update(i);
			else l->update(i),r->update(m+1);

			l->propo(),r->propo();
			vs=l->vs,vm=l->ve,ve=r->ve;
		}
	}

	void update(line i){
		bool lo=i.get(vs)>val.get(vs);
		bool mi=i.get(vm)>val.get(vm);
		bool hi=i.get(ve)>val.get(ve);

		if (mi) swap(i,val);

		if (s==e || i.c==-INF || lo==hi) return;

		l->propo(),r->propo();
		if (lo!=mi) l->update(i);
		else r->update(i);
	}

	ii query(ll i){
		propo();

        if (s==e) return {val.get(vs),vs};
		else if (i<=m){
			auto temp=l->query(i);
			return {max(temp.fi,val.get(temp.se)),temp.se};
		}
		else{
			auto temp=r->query(i);
			return {max(temp.fi,val.get(temp.se)),temp.se};
		}
	}
